mapper.sql:
o.effective_from <= #{criteria.asOf}
AND (o.effective_to IS NULL OR o.effective_to >= #{criteria.asOf})

    AND (
        LOWER(o.organization_code) LIKE CONCAT('%', LOWER(#{criteria.keyword}), '%')
        OR LOWER(o.organization_name) LIKE CONCAT('%', LOWER(#{criteria.keyword}), '%')
    )
